    assertEquals(getTile(8, 6), TILE_SHALLOW_WATER);
    assertEquals(getTile(9, 7), TILE_SHALLOW_WATER);
    assert(!world.has(trap, FloodState), "flood should expire after its volume is placed");
  } finally {
    clearAll();
  }
});

