  const maxHp = vit.maxHp | 0;
  vit.hp = Math.max(0, hpBefore - finalAmount);
  const hpAfter = vit.hp | 0;

  // Step 4b: Queue knockback (resolved by knockbackSystem this tick).
  const kb = spec.knockback;
