function conductedDamage(world, target, type, rawAmount, maxHp) {
  if (type !== "electric" && type !== "lightning" && type !== "plasma") return rawAmount;
  if (!isActorWet(world, target)) return rawAmount;

  const boots = world.get(target, Equipment)?.feet;
  if (boots && world.isAlive(boots) && (
    world.get(boots, Material)?.kind === "rubber" ||
    world.get(boots, ItemInfo)?.affixes?.includes("insulated1")
  )) return rawAmount;

  const waterDamage = Math.ceil(maxHp * ELECTRIC_DAMAGE_TUNING.waterDamageMinMaxHpFraction);
  if (rawAmount >= waterDamage) return rawAmount;

  const luck = Number(resolveCanonicalStats(world, target)?.luck || 0) + statusStrength(world, target, "lucky");
  return luck > 0 && pct(world.rand, luck) ? rawAmount : waterDamage;
}

